const std = @import("std");

pub fn main() !void {
    var arr = [_]i32{ 12, 11, 13, 5, 6 };

    for (1..arr.len) |i| {
        const key = arr[i];
        var j: usize = i;
        while (j > 0 and arr[j - 1] > key) {
            arr[j] = arr[j - 1];
            j -= 1;
        }
        arr[j] = key;
    }

    for (arr) |val| std.debug.print("{} ", .{val});
    std.debug.print("\n", .{});
}
